CREATE TABLE IF NOT EXISTS "COMPONENTLICENSES" (
    "ID" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "COMPONENT_ID" bigint NOT NULL,
    "LICENSE_ID" bigint,
    "LICENSE" text,
    "LICENSE_EXPRESSION" text,
    "LICENSE_URL" text,
    "ORDINALITY" bigint NOT NULL CHECK ("ORDINALITY" > 0),
    "ACKNOWLEDGEMENT" text DEFAULT 'DECLARED' NOT NULL,
    CONSTRAINT "COMPONENTLICENSES_FK1" FOREIGN KEY ("COMPONENT_ID") REFERENCES "COMPONENT"("ID") ON DELETE CASCADE,
    CONSTRAINT "COMPONENTLICENSES_FK2" FOREIGN KEY ("LICENSE_ID") REFERENCES "LICENSE"("ID") ON DELETE CASCADE,
    CONSTRAINT "COMPONENTLICENSES_CHK1" CHECK ("ACKNOWLEDGEMENT" IN ('DECLARED', 'CONCLUDED'))
);

INSERT INTO "COMPONENTLICENSES" (
    "COMPONENT_ID",
    "LICENSE_ID",
    "LICENSE",
    "LICENSE_EXPRESSION",
    "LICENSE_URL",
    "ORDINALITY",
    "ACKNOWLEDGEMENT"
) SELECT "ID", "LICENSE_ID", "LICENSE", "LICENSE_EXPRESSION", "LICENSE_URL", 1, 'DECLARED' FROM "COMPONENT"
	WHERE "COMPONENT"."LICENSE_ID" IS NOT NULL
	    OR "COMPONENT"."LICENSE" IS NOT NULL
	    OR "COMPONENT"."LICENSE_EXPRESSION" IS NOT NULL
	    OR "COMPONENT"."LICENSE_URL" IS NOT NULL;


-- squawk-ignore require-concurrent-index-creation
CREATE UNIQUE INDEX IF NOT EXISTS "COMPONENTLICENSES_ID_IDX"
    ON "COMPONENTLICENSES" ("COMPONENT_ID", "LICENSE_ID")
    WHERE "LICENSE_ID" IS NOT NULL;

-- squawk-ignore require-concurrent-index-creation
CREATE INDEX IF NOT EXISTS "COMPONENTLICENSES_LICENSE_ID_IDX"
    ON "COMPONENTLICENSES" ("LICENSE_ID")
    WHERE "LICENSE_ID" IS NOT NULL;

-- squawk-ignore require-concurrent-index-creation
CREATE UNIQUE INDEX IF NOT EXISTS "COMPONENTLICENSES_EXP_IDX"
    ON "COMPONENTLICENSES" ("COMPONENT_ID", "LICENSE_EXPRESSION")
    WHERE "LICENSE_EXPRESSION" IS NOT NULL;

-- squawk-ignore require-concurrent-index-creation
CREATE INDEX IF NOT EXISTS "COMPONENTLICENSES_COMPONENT_ORDINALITY_IDX"
    ON "COMPONENTLICENSES" ("COMPONENT_ID", "ORDINALITY");